import{_ as t,o as d,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — trend-fit (GĐ1)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/ai-features/trend-fit/plan.md","filePath":"feature/ai-features/trend-fit/plan.md"}'),i={name:"feature/ai-features/trend-fit/plan.md"};function a(c,e,r,s,h,l){return d(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="plan-—-trend-fit-gđ1" tabindex="-1">Plan — trend-fit (GĐ1) <a class="header-anchor" href="#plan-—-trend-fit-gđ1" aria-label="Permalink to &quot;Plan — trend-fit (GĐ1)&quot;">​</a></h1><h2 id="kien-truc" tabindex="-1">Kiến trúc <a class="header-anchor" href="#kien-truc" aria-label="Permalink to &quot;Kiến trúc&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>moments_vn.json ─► moments.py (lunar.py) ─┐</span></span>
<span class="line"><span>trend_formats.json ─► formats             ├─► store.py: TrendItem (3 lớp, tra theo trend_id)</span></span>
<span class="line"><span>Redis trends:v2:{date}:{cat} ─► safety.py ┘            │</span></span>
<span class="line"><span>                                                       ▼</span></span>
<span class="line"><span>BE: brand profile ─► POST /ai/trends/for-brand ─► matching.py</span></span>
<span class="line"><span>                                                   tier1 (luật, chặn cứng) ─► top 20</span></span>
<span class="line"><span>                                                   tier2 (Gemini 1 call, JSON) ─► cache Redis</span></span>
<span class="line"><span>                                                       │</span></span>
<span class="line"><span>web chọn trend ─► BE ─► POST /ai/content/captions/generate {trend_id, techniques, brand_profile, image_urls}</span></span>
<span class="line"><span>                          └► store.get(trend_id) → trend card → caption_service → Gemini (kèm ảnh) → 3 variants</span></span></code></pre></div><h2 id="module-moi-—-app-services-trend-fit" tabindex="-1">Module mới — <code>app/services/trend_fit/</code> <a class="header-anchor" href="#module-moi-—-app-services-trend-fit" aria-label="Permalink to &quot;Module mới — \`app/services/trend_fit/\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Trách nhiệm</th><th>Phụ thuộc</th></tr></thead><tbody><tr><td><code>lunar.py</code></td><td>Đổi âm lịch → dương lịch (thuật toán Hồ Ngọc Đức, múi giờ +7). Không thêm thư viện.</td><td>stdlib <code>math</code>, <code>datetime</code></td></tr><tr><td><code>moments.py</code></td><td>Đọc <code>moments_vn.json</code>; tính lần xảy ra gần nhất; <code>active(day)</code> và <code>upcoming(day, 30)</code> → <code>TrendItem</code></td><td><code>lunar.py</code></td></tr><tr><td><code>safety.py</code></td><td><code>SENSITIVE</code> (+V3) copy từ bộ lọc dataset; <code>event_allowed(candidate)</code></td><td><code>re</code></td></tr><tr><td><code>store.py</code></td><td><code>TrendItem</code>; <code>formats(day)</code>; <code>events(day)</code> từ <code>TrendCacheService</code>; <code>get(trend_id, day)</code></td><td>moments, safety, Redis</td></tr><tr><td><code>matching.py</code></td><td><code>tier1(items, brand)</code>; <code>judge(brand, items)</code> gọi Gemini; <code>for_brand(...)</code> + cache</td><td>llm_service, Redis</td></tr></tbody></table><p>Model Pydantic mới đặt tại <code>app/models/trend_fit_models.py</code>: <code>BrandProfile</code>, <code>TrendItem</code>, <code>TrendMatch</code>, <code>TrendForBrandRequest/Response</code>, <code>BrandProfileExtractRequest</code>, <code>TECHNIQUES</code>.</p><h2 id="đinh-dang-trend-id" tabindex="-1">Định dạng <code>trend_id</code> <a class="header-anchor" href="#đinh-dang-trend-id" aria-label="Permalink to &quot;Định dạng \`trend_id\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lớp</th><th>Mẫu</th><th>Tra cứu</th></tr></thead><tbody><tr><td>moment</td><td><code>moment:{id}:{peak YYYY-MM-DD}</code></td><td>tính lại từ JSON</td></tr><tr><td>format</td><td><code>format:{id}</code></td><td>JSON, kiểm <code>expire_at</code></td></tr><tr><td>event</td><td><code>trend:{date}:{category}:{slug}</code> (đã có ở pipeline)</td><td><code>HGET trends:v2:{date}:{category}:data</code> rồi tới key <code>live</code></td></tr></tbody></table><h2 id="tang-1-s6" tabindex="-1">Tầng 1 (S6) <a class="header-anchor" href="#tang-1-s6" aria-label="Permalink to &quot;Tầng 1 (S6)&quot;">​</a></h2><ul><li>Bảng <code>TOPIC_FIT[topic][industry]</code> ∈ {0,1,2} cho 12 topic PhoBERT × 10 ngành. <code>OTHER</code> = 1 cho mọi topic.</li><li>Moment: hợp nếu <code>industries</code> chứa ngành của brand hoặc <code>*</code>.</li><li>Format: điểm 1 (dùng được mọi ngành trừ khi format ghi <code>industries</code>).</li><li>Chặn cứng: <code>taboos</code> của brand xuất hiện trong text trend; trend sự kiện không qua <code>safety.event_allowed</code>.</li><li>Xếp: điểm hợp → moment đang ở cửa sổ đỉnh → <code>final_score</code> của sự kiện. Lấy 20.</li><li>shortcut: chưa có embedding brand↔trend; thêm khi luật bỏ sót nhiều (đo bằng bộ nhãn tay ở test.md).</li></ul><h2 id="tang-2-s7-—-gemini-json-mode-retry-429-5xx" tabindex="-1">Tầng 2 (S7) — Gemini JSON mode, retry 429/5xx <a class="header-anchor" href="#tang-2-s7-—-gemini-json-mode-retry-429-5xx" aria-label="Permalink to &quot;Tầng 2 (S7) — Gemini JSON mode, retry 429/5xx&quot;">​</a></h2><ul><li>1 lần gọi Gemini cho cả ≤20 ứng viên → JSON <code>{&quot;items&quot;:[{trend_id, relevance, voice_fit, timing, risk, verdict, reason, techniques}]}</code>.</li><li>Kiểm hậu kỳ: bỏ <code>trend_id</code> lạ; verdict ngoài enum → bỏ item; techniques lọc theo enum, tối đa 2; moment <code>solemn</code> ép techniques = <code>[&quot;khoanh_khac&quot;]</code>.</li><li>Xếp: <code>nen</code> trước <code>can_nhac</code>, rồi tổng <code>relevance + voice_fit + timing - risk</code>.</li><li>Cache: <code>trendfit:{client_id}:{date}:{sha1(brand)[:12]}</code>, TTL 24h. Đổi hồ sơ → hash khác → chấm lại.</li><li>Lỗi (<code>LLMQualityError</code>, <code>httpx.HTTPError</code>, <code>RuntimeError</code> chưa init client) → fallback tầng 1, <code>judged=false</code>.</li></ul><h2 id="viet-bai-s9–s11" tabindex="-1">Viết bài (S9–S11) <a class="header-anchor" href="#viet-bai-s9–s11" aria-label="Permalink to &quot;Viết bài (S9–S11)&quot;">​</a></h2><ul><li>Endpoint <code>/captions/generate</code> thành <code>async</code>: nếu có <code>trend_id</code> thì <code>await store.get(...)</code>, rồi chạy <code>generate_caption_variants(request, trend)</code> trong threadpool (giữ nguyên code sync hiện có).</li><li>Prompt thêm 4 khối khi có dữ liệu: <strong>trend card</strong>, <strong>giọng brand</strong> (mức ngôn ngữ + xưng hô + emoji + fan + sự thật + điều cấm), <strong>5 kỹ thuật</strong> (định nghĩa 1 dòng mỗi kỹ thuật, ưu tiên <code>techniques</code> từ for-brand), <strong>luật</strong> (prompt user &gt; giọng brand; fact chỉ từ brand/trend/prompt/ảnh; moment trang trọng: không đùa, không khuyến mãi).</li><li>JSON mỗi variant thêm <code>&quot;trend_technique&quot;</code>. Giá trị lạ → <code>null</code> (không fail cả response).</li><li>Ảnh: <code>GeminiClient.generate(prompt, images=())</code> gửi <code>inlineData</code>; <code>llm_service.generate_text(..., images=())</code> có ảnh thì đi thẳng Gemini (Groq không đọc ảnh).</li><li><code>signals.issues</code>: <code>foreign_script</code> (Hangul/CJK/Thái), <code>prompt_leak</code>, <code>sensitive</code>, <code>too_long</code>. Chạy cho cả refine/adapt.</li><li>Khi có fine-tune model (GĐ sau): thay đúng lời gọi <code>llm_service.generate_text</code> trong <code>caption_service</code>, gọi 3 lần/1 kỹ thuật như thiết kế S10 — schema response không đổi.</li></ul><h2 id="ho-so-brand-s5" tabindex="-1">Hồ sơ brand (S5) <a class="header-anchor" href="#ho-so-brand-s5" aria-label="Permalink to &quot;Hồ sơ brand (S5)&quot;">​</a></h2><ul><li><code>POST /api/v1/ai/content/brand-profile/extract</code>: <code>knowledge_chunks(client_id, ...)</code> (đã có) + mô tả/website → Gemini → <code>BrandProfile</code>.</li><li>BE lưu (JSONB) và web cho user sửa/xác nhận: <strong>chưa làm</strong> (repo BE/web đang dở việc khác).</li></ul><h2 id="noi-vao-web-chinh-gđ1b" tabindex="-1">Nối vào web chính (GĐ1b) <a class="header-anchor" href="#noi-vao-web-chinh-gđ1b" aria-label="Permalink to &quot;Nối vào web chính (GĐ1b)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repo</th><th>File</th><th>Thay đổi</th></tr></thead><tbody><tr><td>business-service</td><td><code>controller/AiCaptionController.java</code></td><td><code>GET /workspaces/{id}/ai/trend-fit</code></td></tr><tr><td>business-service</td><td><code>service/ai/AiCaptionService.java</code></td><td><code>trendFit()</code>; <code>Request.trendId/techniques</code>; map <code>trend_technique</code>, <code>signals.issues</code></td></tr><tr><td>business-service</td><td><code>service/ai/CaptionContextService.java</code></td><td><code>brandProfile()</code> dựng từ workspace</td></tr><tr><td>business-service</td><td><code>test/.../AiCaptionServiceTest.java</code>, <code>CaptionContextServiceTest.java</code></td><td>test mới</td></tr><tr><td>brandhub-web</td><td><code>services/aiCaptionService.ts</code></td><td>kiểu <code>FitTrend</code>, <code>TrendFit</code>; <code>trendFit()</code>; <code>trendId/techniques</code></td></tr><tr><td>brandhub-web</td><td><code>components/ai/AiCaptionDialog.tsx</code></td><td>khối <code>BrandFitTrends</code>; chip góc nối + <code>issues</code></td></tr><tr><td>brandhub-web</td><td><strong><code>i18n/locales/vi/aiStudio.json</code>, <code>i18n/locales/en/aiStudio.json</code></strong></td><td>khối <code>trendFit</code></td></tr></tbody></table><p>Công cụ test ngoài dự án (không push): <code>khongpush_gihub_MCP/content-pipeline-ui/pages/1_Trend_fit.py</code> (Streamlit, xem từng bước S1→S11, duyệt S1/S2), <code>run_api.bat</code> (API cổng 8090 cho Swagger).</p><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rủi ro</th><th>Giảm thiểu</th></tr></thead><tbody><tr><td>Gemini chấm sai/thiên vị</td><td>Bộ nhãn tay 30 cặp đo độ khớp; luật chặn cứng chạy trước LLM</td></tr><tr><td>Trend sự kiện ít vì luật <code>rising/peaking</code> gắt</td><td>Đo số trend còn lại trên dữ liệu thật; nới sang <code>new</code> nếu cần (1 dòng)</td></tr><tr><td>Format/meme hết hot</td><td><code>expire_at</code> bắt buộc; người duyệt hằng tuần</td></tr><tr><td>Ngày âm lịch sai</td><td>Test với Tết/Trung thu đã biết các năm 2023–2026</td></tr><tr><td>Free tier Gemini dùng dữ liệu để train</td><td>Production dùng key trả phí</td></tr></tbody></table>`,21)])])}const m=t(i,[["render",a]]);export{u as __pageData,m as default};
